# -*- coding: utf-8 -*-
"""España / Conocimiento del Medio: 5.º y 6.º de Primaria（tercer ciclo）"""
from es_sci import H, nq, num, it


def f_dens(R):
    k = R.choice(["d", "d", "m", "V", "flota"])
    if k == "d":
        m, V = R.choice([(200, 100), (540, 200), (78, 10), (450, 500), (90, 100), (190, 10), (300, 400), (2700, 1000), (60, 50), (800, 1000), (1130, 100)])
        return nq("Un objeto tiene una masa de %s g y un volumen de %s cm³. ¿Cuál es su densidad?" % (num(m), num(V)), m / V, [m * V, V / m, m - V], "g/cm³",
                  "Densidad = masa : volumen = %s : %s = %s g/cm³." % (num(m), num(V), num(m / V)))
    if k == "m":
        d, V = R.choice([(2.7, 10), (1, 250), (7.8, 5), (0.9, 100), (19.3, 2), (0.5, 40), (8.9, 10), (1.2, 50)])
        return nq("Un material tiene una densidad de %s g/cm³. ¿Qué masa tienen %s cm³?" % (num(d), num(V)), d * V, [d / V, V / d, d + V], "g",
                  "Masa = densidad × volumen = %s × %s = %s g." % (num(d), num(V), num(d * V)))
    if k == "V":
        d, m = R.choice([(2, 50), (8, 400), (0.5, 20), (4, 100), (10, 250), (5, 60), (2.5, 75)])
        return nq("Una pieza de %s g tiene una densidad de %s g/cm³. ¿Qué volumen ocupa?" % (num(m), num(d)), m / d, [m * d, d / m, m - d], "cm³",
                  "Volumen = masa : densidad = %s : %s = %s cm³." % (num(m), num(d), num(m / d)))
    m, V = R.choice([(30, 40), (45, 50), (120, 100), (90, 60), (16, 20), (70, 50), (25, 50), (110, 100)])
    d = m / V
    a = "flota" if d < 1 else "se hunde"
    return it("Un objeto de %s g ocupa %s cm³. El agua tiene una densidad de 1 g/cm³. ¿Qué hace el objeto en el agua?" % (num(m), num(V)), a,
              ["se hunde" if a == "flota" else "flota", "se disuelve", "flota y después se hunde"],
              "Su densidad es %s : %s = %s g/cm³, %s que la del agua: %s." % (num(m), num(V), num(d), "menor" if d < 1 else "mayor", a))


def f_vel(R):
    k = R.choice(["v", "v", "d", "t", "kmh"])
    if k == "v":
        d, t = R.choice([(100, 20), (60, 12), (400, 80), (150, 3), (240, 4), (90, 3), (500, 100), (36, 4)])
        u, ut = ("km", "h") if d in (150, 240, 90) else ("m", "s")
        return nq("Un móvil recorre %s %s en %s %s. ¿Cuál es su velocidad?" % (num(d), u, num(t), ut), d / t, [d * t, t / d, d - t], "%s/%s" % (u, ut),
                  "Velocidad = distancia : tiempo = %s : %s = %s %s/%s." % (num(d), num(t), num(d / t), u, ut))
    if k == "d":
        v, t = R.choice([(80, 3), (5, 60), (120, 2), (12, 10), (60, 4), (4, 25), (90, 2)])
        u, ut = ("km", "h") if v >= 60 else ("m", "s")
        return nq("Un vehículo va a %s %s/%s durante %s %s. ¿Qué distancia recorre?" % (num(v), u, ut, num(t), ut), v * t, [v / t, v + t, t / v], u,
                  "Distancia = velocidad × tiempo = %s × %s = %s %s." % (num(v), num(t), num(v * t), u))
    if k == "t":
        d, v = R.choice([(240, 80), (300, 100), (180, 60), (100, 5), (450, 90), (60, 4)])
        u, ut = ("km", "h") if v >= 60 else ("m", "s")
        return nq("¿Cuánto tarda en recorrer %s %s algo que va a %s %s/%s?" % (num(d), u, num(v), u, ut), d / v, [d * v, v / d, d - v], ut,
                  "Tiempo = distancia : velocidad = %s : %s = %s %s." % (num(d), num(v), num(d / v), ut))
    v = R.choice([10, 20, 5, 15, 25, 30])
    return nq("Un ciclista va a %s m/s. ¿Cuántos km/h son? (1 m/s = 3,6 km/h)" % num(v), v * 3.6, [v / 3.6, v * 60, v * 1000], "km/h",
              "%s × 3,6 = %s km/h." % (num(v), num(v * 3.6)))


